package com.nextaicommerce.platform.sync;
import java.time.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.ObjectMapper;
import static org.assertj.core.api.Assertions.*;
class FbaFinanceWindowTest {
 final Instant now=Instant.parse("2026-11-21T03:00:00Z");
 AmazonSyncStore.Job job(Instant start,Instant end){return new AmazonSyncStore.Job(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"FBA_INBOUND","FBA_MANUAL","ATVPDKIKX0DER",start,end,null,0,0,false,null);}
 Map<String,String> query(String path){var result=new HashMap<String,String>();for(String part:path.substring(path.indexOf('?')+1).split("&")){var pair=part.split("=",2);result.put(pair[0],URLDecoder.decode(pair[1],StandardCharsets.UTF_8));}return result;}
 @Test void pointInTimeShipmentRunStillRequestsPositiveBoundedFinanceWindow(){var end=Instant.parse("2026-11-20T22:35:13.306946Z");var q=query(FbaInboundSync.financePath(job(end,end),new ObjectMapper().createObjectNode(),now));assertThat(Instant.parse(q.get("postedBefore"))).isAfter(Instant.parse(q.get("postedAfter")));}
 @Test void fallbackIsSevenDaysAndRecentEndIsEligibleThenFrozenAcrossTokenPages(){var cursor=new ObjectMapper().createObjectNode();var job=job(now,now);var first=query(FbaInboundSync.financePath(job,cursor,now));var end=Instant.parse(first.get("postedBefore"));assertThat(end).isEqualTo(now.minusSeconds(121));assertThat(Instant.parse(first.get("postedAfter"))).isEqualTo(end.minus(Duration.ofDays(7)));cursor.put("feeNext","opaque+a&b");var next=query(FbaInboundSync.financePath(job,cursor,now.plusSeconds(600)));assertThat(next.get("postedAfter")).isEqualTo(first.get("postedAfter"));assertThat(next.get("postedBefore")).isEqualTo(first.get("postedBefore"));assertThat(next.get("nextToken")).isEqualTo("opaque+a&b");}
 @Test void validNarrowWindowIsPreservedAndOldHistoryIsClamped(){var json=new ObjectMapper();var end=now.minusSeconds(1000);var shortStart=end.minus(Duration.ofDays(2));assertThat(query(FbaInboundSync.financePath(job(shortStart,end),json.createObjectNode(),now)).get("postedAfter")).isEqualTo(shortStart.toString());assertThat(query(FbaInboundSync.financePath(job(end.minus(Duration.ofDays(300)),end),json.createObjectNode(),now)).get("postedAfter")).isEqualTo(end.minus(Duration.ofDays(180)).toString());}
 @Test void reversedWindowUsesBoundedFallback(){var cursor=new ObjectMapper().createObjectNode();var end=now.minusSeconds(1000);var q=query(FbaInboundSync.financePath(job(end.plusSeconds(5),end),cursor,now));assertThat(q.get("postedAfter")).isEqualTo(end.minus(Duration.ofDays(7)).toString());}
 @Test void legacyTokenAndFailureAreArchivedOnceButNeverReusedWithNewRange(){var cursor=new ObjectMapper().createObjectNode().put("feeQueryRevision",2).put("feeNext","old-token").put("feesUnavailable",true).put("feeFailureStatus",400);var job=job(now,now);assertThat(query(FbaInboundSync.financePath(job,cursor,now))).doesNotContainKey("nextToken");assertThat(cursor.path("feeQueryHistory")).hasSize(1);assertThat(cursor.path("feeQueryHistory").get(0).path("feeNext").asText()).isEqualTo("old-token");assertThat(cursor.path("feeQueryHistory").get(0).path("feeFailureStatus").asInt()).isEqualTo(400);cursor.put("feeNext","new-token");assertThat(query(FbaInboundSync.financePath(job,cursor,now.plusSeconds(600))).get("nextToken")).isEqualTo("new-token");assertThat(cursor.path("feeQueryHistory")).hasSize(1);}
 @Test void malformedOrChangedSavedContractFailsClosedWithoutDiscardingToken(){var cursor=new ObjectMapper().createObjectNode().put("feeQueryRevision",3).put("feeNext","keep");var job=job(now,now);assertThatThrownBy(()->FbaInboundSync.financePath(job,cursor,now)).isInstanceOf(IllegalStateException.class);assertThat(cursor.path("feeNext").asText()).isEqualTo("keep");cursor.remove("feeQueryRevision");FbaInboundSync.financePath(job,cursor,now);cursor.put("feeQueryMarketplace","OTHER").put("feeNext","keep-again");assertThatThrownBy(()->FbaInboundSync.financePath(job,cursor,now.plusSeconds(600))).isInstanceOf(IllegalStateException.class);assertThat(cursor.path("feeNext").asText()).isEqualTo("keep-again");}
}
